-- Athena saved query (Product_B2C_Intl)
-- ID: 93170133-2146-4348-84d3-7289136c4cb2
-- Name: Bus Images Funnel - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH base AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, event_group, event_name, UPPER(usertype) usertype, mri_session_id, bus_operator op_id, route_id_train_no route_id FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-05-26 18:30:00' AND __time < TIMESTAMP '2026-06-01 18:30:00' AND app_code > 859110 -- AND event_group = 'NewBusImageLoaded' AND event_name IN ('NewBusImageLoaded') GROUP BY 1, 2, 3, 4, 5, 6, 7 ), mpax_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-05-26 18:30:00' AND __time < TIMESTAMP '2026-06-01 18:30:00' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-05-26 18:30:00' AND __time < TIMESTAMP '2026-06-01 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-05-26 18:30:00' AND __time < TIMESTAMP '2026-06-01 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT b.event_group, b.event_name, b.usertype, COUNT(DISTINCT b.mri_session_id) SL, COUNT(DISTINCT mp.mri_session_id) CI, COUNT(DISTINCT oi.mri_session_id) Pay, COUNT(DISTINCT c.mri_session_id) Confirm FROM base b LEFT JOIN mpax_deduped mp ON mp.mri_session_id = b.mri_session_id AND mp.route_id = CAST(b.route_id AS BIGINT) LEFT JOIN orderinfo_deduped oi ON oi.mri_session_id = b.mri_session_id AND oi.route_id = CAST(b.route_id AS BIGINT) LEFT JOIN confirm_deduped c ON c.mri_session_id = b.mri_session_id AND c.route_id = CAST(b.route_id AS BIGINT) GROUP BY 1, 2, 3
